INSERT INTO products (handle, title, short_title, price, compare_at_price, price_from, badge, image, cat_handle, cat_label, colour, colour_hex, summary, description, features, specs, shipping_note, collection_handle, sold_out, is_new, show_in_home_grid, sort_order, seo_title, seo_description) VALUES
  ('outdoor-b-bag-grey', 'Outdoor B-Bag - Grey', '', 64.99, NULL, 1, '', '/images/outdoor-b-bag-grey.png', 'outdoor', 'Outdoor', 'Grey', '#5f6062', 'The original outdoor bean bag, built for the garden, the beach and everything in between.', 'Engineered to defeat the elements, the Outdoor B-bag takes lounging to new places and extremes. All eleven fabric colours are fade-resistant even in direct sunlight. Plus the tough and waterproof fabric of our outdoor bean bags is double-stitched for extra durability.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Vents","value":"Breathable vents release air quickly"},{"label":"Stitching","value":"Double stitched for durability"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 1, 'Outdoor B-Bag - Grey | Chen Furniture', 'The original outdoor bean bag, built for the garden, the beach and everything in between.'),
  ('b-lamp-grey', 'B-Lamp - Grey', '', 59.99, NULL, 0, 'NEW', '/images/b-lamp-grey.png', 'lighting', 'Lighting', 'Grey', '#5f6062', 'A portable, rechargeable lamp that brings the glow wherever you lounge.', 'The B-Lamp is a wireless, dimmable light with a warm glow that is just as at home on a garden table as it is beside the sofa. Charge it indoors, then take it outside for up to 24 hours of light per charge.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Battery","value":"Rechargeable, up to 24 hours per charge"},{"label":"Charge time","value":"Approximately 4 hours (USB-C)"},{"label":"Weather rating","value":"Suitable for use indoors and outdoors"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'lighting-all-styles', 0, 1, 1, 2, 'B-Lamp - Grey | Chen Furniture', 'A portable, rechargeable lamp that brings the glow wherever you lounge.'),
  ('outdoor-b-poufe-grey', 'Outdoor B-Poufe - Grey', '', 79.99, NULL, 0, '', '/images/outdoor-b-poufe-grey.png', 'outdoor', 'Outdoor', 'Grey', '#5f6062', 'Part pouffe, part footstool, all comfort - indoors or out.', 'The Outdoor B-Poufe is the perfect sidekick to a B-Bag. Use it as a footstool, an extra seat for unexpected guests or a table-top for drinks when you add a tray. The water resistant fabric wipes clean in seconds.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Height","value":"45cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 3, 'Outdoor B-Poufe - Grey | Chen Furniture', 'Part pouffe, part footstool, all comfort - indoors or out.'),
  ('b-cushion-bright-grey', 'B-Cushion Brights - Grey', '', 14.99, NULL, 0, '', '/images/b-cushion-brights-grey.png', 'accessories', 'Accessories', 'Grey', '#5f6062', 'Add a splash of colour to any B-Bag or sofa.', 'Our B-Cushions are the easiest way to brighten up a B-Bag, B-Bed or sofa. Made from the same water resistant fabric as our outdoor range so they can happily live in the garden, and the covers are machine washable.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Size","value":"45cm x 45cm"},{"label":"Care","value":"Machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-cushion', 0, 0, 1, 4, 'B-Cushion Brights - Grey | Chen Furniture', 'Add a splash of colour to any B-Bag or sofa.'),
  ('outdoor-b-hammock-grey', 'Outdoor B-Hammock - Grey', '', 449.99, NULL, 0, '', '/images/outdoor-b-hammock-grey.png', 'outdoor', 'Outdoor', 'Grey', '#5f6062', 'A freestanding hammock you can set up anywhere the sun happens to be.', 'The B-Hammock is a freestanding, powder coated steel frame hammock with a water resistant bean filled bed. No trees, no drilling and no straps required - just unfold, lounge and let the afternoon disappear.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Frame","value":"Powder coated steel, freestanding"},{"label":"Bed","value":"Water resistant 100% polyester with bead filling"},{"label":"Max load","value":"150kg"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 5, 'Outdoor B-Hammock - Grey | Chen Furniture', 'A freestanding hammock you can set up anywhere the sun happens to be.'),
  ('b-bulb-clear', 'B-Bulb - Clear', '', 49.99, NULL, 1, '', '/images/b-bulb.png', 'lighting', 'Lighting', '', '#5f6062', 'The original portable B-Bulb, now with a rechargeable base.', 'The B-Bulb is a fully portable, dimmable lamp with a classic filament look and a soft, warm glow. Because it is battery powered and splash resistant you can move it from kitchen table to garden without hunting for a socket.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Battery","value":"Rechargeable, 12-24 hours per charge"},{"label":"Charge time","value":"Approximately 4 hours (USB-C)"},{"label":"Weather rating","value":"Splash resistant, IP44"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'lighting-all-styles', 0, 0, 1, 6, 'B-Bulb - Clear | Chen Furniture', 'The original portable B-Bulb, now with a rechargeable base.'),
  ('b-chair-ecru-copy', 'B-Chair - Charcoal', '', 199.99, NULL, 0, '', '/images/b-chair-charcoal.png', 'indoor', 'Indoor', 'Charcoal', '#3a3d40', 'A statement lounging chair with a giant bean bag heart.', 'The B-Chair takes everything you love about a bean bag and gives it a frame. The bead filled seat moulds to you while the supportive back and armrests keep you sitting pretty. Finished in the same hardwearing fabrics as our B-Bags.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Dimensions","value":"H: 70cm  W: 85cm  L: 80cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'indoor-range', 0, 0, 1, 7, 'B-Chair - Charcoal | Chen Furniture', 'A statement lounging chair with a giant bean bag heart.'),
  ('b-dogbed-grey', 'B-Dogbed - Grey', '', 99.99, NULL, 1, '', '/images/b-dogbed-grey.png', 'pets', 'Pets', 'Grey', '#5f6062', 'The bean bag bed your dog will claim as their own.', 'B-Dogbed gives your four legged friend the same bead filled comfort as a B-Bag, with a low front lip that makes it easy to step in and out. The water resistant, removable cover is machine washable so muddy paws are never a problem.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Care","value":"Removable, machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'pets-range', 0, 0, 1, 8, 'B-Dogbed - Grey | Chen Furniture', 'The bean bag bed your dog will claim as their own.'),
  ('outdoor-b-bed-grey', 'Outdoor B-Bed - Grey', '', 249.99, NULL, 0, '', '/images/outdoor-b-bed-grey.png', 'outdoor', 'Outdoor', 'Grey', '#5f6062', 'A full length lounger for serious sunbathing.', 'Some afternoons deserve more than a bean bag. The Outdoor B-Bed is a full length, bead filled lounger that shapes itself around you, so you can stretch out, roll over and stay put for hours.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Dimensions","value":"H: 40cm  W: 80cm  L: 190cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 9, 'Outdoor B-Bed - Grey | Chen Furniture', 'A full length lounger for serious sunbathing.'),
  ('outdoor-b-bolster-grey', 'Outdoor B-Bolster - Grey', '', 24.99, NULL, 0, '', '/images/outdoor-b-bolster-grey.png', 'accessories', 'Accessories', 'Grey', '#5f6062', 'The roll-shaped cushion that props up any B-Bag.', 'Pop a B-Bolster behind your back for extra support or under your knees to properly switch off. It is made from the same weatherproof fabric as our B-Bags, so it can stay outside all summer.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Size","value":"60cm x 20cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 10, 'Outdoor B-Bolster - Grey | Chen Furniture', 'The roll-shaped cushion that props up any B-Bag.');
INSERT INTO products (handle, title, short_title, price, compare_at_price, price_from, badge, image, cat_handle, cat_label, colour, colour_hex, summary, description, features, specs, shipping_note, collection_handle, sold_out, is_new, show_in_home_grid, sort_order, seo_title, seo_description) VALUES
  ('b-pad-grey', 'B-Pad - Grey', '', 49.99, NULL, 0, '', '/images/b-pad-grey.png', 'accessories', 'Accessories', 'Grey', '#5f6062', 'A quilted comfort layer that turns any B-Bag into a day bed.', 'The B-Pad is a quilted topper that adds a softer, flatter surface to your B-Bag, B-Poufe or B-Bed. Perfect for picnics, yoga in the garden or simply making your favourite seat a little more luxurious.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Filling","value":"Polyester wadding"},{"label":"Size","value":"130cm x 75cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 11, 'B-Pad - Grey | Chen Furniture', 'A quilted comfort layer that turns any B-Bag into a day bed.'),
  ('b-blanket-grey', 'B-Blanket - Grey', '', 59.99, NULL, 0, '', '/images/b-blanket-grey.png', 'accessories', 'Accessories', 'Grey', '#5f6062', 'Stay cosy anywhere with our outdoor ready throw.', 'The B-Blanket is a generously sized, water resistant throw with a soft brushed reverse. Keep one on the back of the sofa and one on the garden bench - you will wonder how you managed without it.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester with brushed reverse"},{"label":"Size","value":"150cm x 200cm"},{"label":"Care","value":"Machine washable at 30 degrees"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-blanket', 0, 0, 1, 12, 'B-Blanket - Grey | Chen Furniture', 'Stay cosy anywhere with our outdoor ready throw.'),
  ('pastel-b-poufe-natural', 'Pastel B-Poufe - Natural', '', 79.99, NULL, 0, '', '/images/pastel-b-poufe-natural.png', 'outdoor', 'Outdoor', 'Natural', '#e4dcc9', 'The Pastel B-Poufe in natural - footstool, extra seat and side table in one.', 'The Pastel B-Poufe brings our most popular footstool into a gentle new colour range that sits beautifully with pale decking, stone terraces and neutral interiors. Bead filled for comfort, water resistant for the outdoors.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Height","value":"45cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 13, 'Pastel B-Poufe - Natural | Chen Furniture', 'The Pastel B-Poufe in natural - footstool, extra seat and side table in one.'),
  ('pastel-b-poufe-pistache', 'Pastel B-Poufe - Pistache', '', 79.99, NULL, 0, '', '/images/pastel-b-poufe-pistache.png', 'outdoor', 'Outdoor', 'Pistache', '#b6c983', 'The Pastel B-Poufe in pistache - footstool, extra seat and side table in one.', 'The Pastel B-Poufe brings our most popular footstool into a gentle new colour range that sits beautifully with pale decking, stone terraces and neutral interiors. Bead filled for comfort, water resistant for the outdoors.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Height","value":"45cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 14, 'Pastel B-Poufe - Pistache | Chen Furniture', 'The Pastel B-Poufe in pistache - footstool, extra seat and side table in one.'),
  ('pastel-b-poufe-dark-grey', 'Pastel B-Poufe - Dark Grey', '', 79.99, NULL, 0, '', '/images/pastel-b-poufe-dark-grey.png', 'outdoor', 'Outdoor', 'Dark Grey', '#4a4d50', 'The Pastel B-Poufe in dark grey - footstool, extra seat and side table in one.', 'The Pastel B-Poufe brings our most popular footstool into a gentle new colour range that sits beautifully with pale decking, stone terraces and neutral interiors. Bead filled for comfort, water resistant for the outdoors.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Height","value":"45cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 15, 'Pastel B-Poufe - Dark Grey | Chen Furniture', 'The Pastel B-Poufe in dark grey - footstool, extra seat and side table in one.'),
  ('pastel-b-poufe-lagoon-blue', 'Pastel B-Poufe - Lagoon Blue', '', 79.99, NULL, 0, '', '/images/pastel-b-poufe-lagoon-blue.png', 'outdoor', 'Outdoor', 'Lagoon Blue', '#2f8f9d', 'The Pastel B-Poufe in lagoon blue - footstool, extra seat and side table in one.', 'The Pastel B-Poufe brings our most popular footstool into a gentle new colour range that sits beautifully with pale decking, stone terraces and neutral interiors. Bead filled for comfort, water resistant for the outdoors.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant, fade resistant 100% polyester"},{"label":"Filling","value":"Polystyrene beads"},{"label":"Height","value":"45cm"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'outdoor-range', 0, 0, 1, 16, 'Pastel B-Poufe - Lagoon Blue | Chen Furniture', 'The Pastel B-Poufe in lagoon blue - footstool, extra seat and side table in one.'),
  ('b-cushion-art-collection-monkey', 'B-Cushion Art Collection - Monkey', '', 19.99, NULL, 0, '', '/images/b-cushion-art-monkey.png', 'accessories', 'Accessories', '', '#5f6062', 'A hand picked art print on our classic water resistant B-Cushion.', 'Part of the B-Cushion Art Collection: the same water resistant B-Cushion you know, printed with artwork from our in-house design studio. Choose a favourite or mix a few for a garden that looks as good as it feels.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Size","value":"45cm x 45cm"},{"label":"Care","value":"Machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-cushion-art-collection', 0, 0, 0, 1000, 'B-Cushion Art Collection - Monkey | Chen Furniture', 'A hand picked art print on our classic water resistant B-Cushion.'),
  ('b-cushion-art-collection-tropical-palm', 'B-Cushion Art Collection - Tropical Palm', '', 19.99, NULL, 0, '', '/images/b-cushion-art-tropical-plam-816e4c25-ff8f-4ac7-8289-e71b83ed344d.png', 'accessories', 'Accessories', '', '#5f6062', 'A hand picked art print on our classic water resistant B-Cushion.', 'Part of the B-Cushion Art Collection: the same water resistant B-Cushion you know, printed with artwork from our in-house design studio. Choose a favourite or mix a few for a garden that looks as good as it feels.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Size","value":"45cm x 45cm"},{"label":"Care","value":"Machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-cushion-art-collection', 0, 0, 0, 1001, 'B-Cushion Art Collection - Tropical Palm | Chen Furniture', 'A hand picked art print on our classic water resistant B-Cushion.'),
  ('b-cushion-art-collection-flower-power', 'B-Cushion Art Collection - Flower Power', '', 19.99, NULL, 0, '', '/images/b-cushion-art-flower-power.png', 'accessories', 'Accessories', '', '#5f6062', 'A hand picked art print on our classic water resistant B-Cushion.', 'Part of the B-Cushion Art Collection: the same water resistant B-Cushion you know, printed with artwork from our in-house design studio. Choose a favourite or mix a few for a garden that looks as good as it feels.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Size","value":"45cm x 45cm"},{"label":"Care","value":"Machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-cushion-art-collection', 0, 0, 0, 1002, 'B-Cushion Art Collection - Flower Power | Chen Furniture', 'A hand picked art print on our classic water resistant B-Cushion.'),
  ('b-cushion-art-collection-sea-blue', 'B-Cushion Art Collection - Sea Blue', '', 19.99, NULL, 0, '', '/images/b-cushion-art-oasis-leaf-sea-blue.png', 'accessories', 'Accessories', '', '#5f6062', 'A hand picked art print on our classic water resistant B-Cushion.', 'Part of the B-Cushion Art Collection: the same water resistant B-Cushion you know, printed with artwork from our in-house design studio. Choose a favourite or mix a few for a garden that looks as good as it feels.', '["Polystyrene Bead Filling","Double Stitched for Durability","Made in UK"]', '[{"label":"Fabric","value":"Water resistant 100% polyester"},{"label":"Size","value":"45cm x 45cm"},{"label":"Care","value":"Machine washable cover"},{"label":"Designed & made","value":"Yorkshire, UK"}]', '', 'b-cushion-art-collection', 0, 0, 0, 1003, 'B-Cushion Art Collection - Sea Blue | Chen Furniture', 'A hand picked art print on our classic water resistant B-Cushion.');
