  (NULL, 'Water Resistant', 'Durable water resistant fabric (100% polyester) suitable for outdoor use', '/images/usp-water-resistant.svg', 1),
  (NULL, 'UV Resistant', 'UV Resistant Material is fade resistant, even in direct sunlight. *In extreme weather, we recommend covering or sheltering the product.', '/images/usp-uv-resistant.svg', 2),
