  (NULL, 'Breathable Vents', 'Breathable vents release air rapidly to maintain the flexibility needed to take your shape quickly without putting pressure on seams', '/images/usp-breathable-vents.svg', 4),
  (NULL, 'Made in the UK', 'Every aspect of our B-products are designed and made in the UK to guarantee material quality and excellent craftsmanship. Based in Yorkshire, Chen Furniture strongly believe that the best products are British through and through.', '/images/usp-made-in-uk.svg', 5);
