INSERT INTO sections (page, type, name, position, enabled, data) VALUES
  ('home', 'hero', 'Homepage carousel', 1, 1, '{"interval":3000,"slides":[{"interval":5000,"url":"/collections/outdoor-range","title":"Embrace the Outdoors","text":"","button":{"label":"Shop Outdoor","url":"/collections/outdoor-range","style":"btn-white","color":"#000000"},"video":"/images/hero-outdoor-desktop.mp4","video_mobile":"/images/hero-outdoor-mobile.mp4","poster":"/images/hero-outdoor-poster-desktop.jpg","poster_mobile":"/images/hero-outdoor-poster-mobile.jpg"}]}'),
  ('home', 'product_row', 'All Products', 2, 1, '{"heading":"All Products","subheading":"","source":"grid","pickers":[],"view_all":{"label":"VIEW ALL","url":"/collections/outdoor-range"}}'),
  ('home', 'link_grid', 'Shop Outdoor / Shop Indoor', 3, 1, '{"items":[{"label":"Shop Outdoor","image":"/images/banner-shop-outdoor.jpg","url":"/collections/outdoor-range","height":"60vh"},{"label":"Shop Indoor","image":"/images/banner-shop-indoor.jpg","url":"/collections/indoor-range","height":"60vh"}]}'),
  ('home', 'image_banner', 'Are you sitting comfortably?', 4, 1, '{"image":"/images/banner-facts.jpg","object_position":"88.1869% 85.9167%","title":"Are you sitting comfortably?","text":"We source all of our materials for our luxury bean bags from as close to home as possible. Not only that, we strive to make everything we do as environmentally friendly as we can. And we do all of this in the cause of creating an uber-comfortable place for you to plonk your posterior."}');
INSERT INTO sections (page, type, name, position, enabled, data) VALUES
  ('home', 'product_row', 'New Products', 5, 1, '{"heading":"New Products","subheading":"","source":"collection","pickers":[{"label":"B-Cushion Art Collection","collection":"b-cushion-art-collection"},{"label":"B-Mat","collection":"b-mat"}],"view_all":{"label":"VIEW ALL","url":"/collections/b-cushion-art-collection"}}'),
  ('home', 'image_banner', 'Keep Cosy Anywhere', 6, 1, '{"image":"/images/banner-b-blanket.png","title":"Keep Cosy Anywhere","text":"","button":{"label":"EXPLORE B-BLANKET","url":"/collections/b-blanket","style":"btn-white","color":"#18181B"}}'),
  ('home', 'masonry', 'Discover Products & Ranges', 7, 1, '{"heading":"Discover Products & Ranges","intro":"Some of our other products & ranges perfect for your furniture collection","span_rows":2,"items":[{"label":"B-Poufe","image":"/images/modular-b-poufe.png","url":"/collections/b-poufe-all-styles","span":"g-col-6 g-col-md-3","align":"align-items-start"},{"label":"Cushions","image":"/images/modular-cushions.png","url":"/collections/b-cushion","span":"g-col-6 g-col-md-3","align":"align-items-start"},{"label":"Lighting","image":"/images/modular-lighting.png","url":"/collections/lighting-all-styles","span":"g-col-12 g-col-md-6 row-span-md-2","align":"align-items-center"},{"label":"B-Dogbed","image":"/images/modular-dogbed.png","url":"/collections/pets-range","span":"g-col-12 g-col-md-6","align":"align-items-start"}]}'),
  ('page:delivery', 'page', 'Delivery Details', 1, 1, '{"title":"Delivery Details","body":"<p>Products are guaranteed to be delivered within 3-5 working days, after receipt of full payment provided your order and payment is received by us before 1:00 p.m. (UK) on Mondays to Thursdays and before 11:00 a.m. on Fridays. We are unable to deliver on Saturdays and Sundays so those days will not count when calculating the 3-5 days. So, for example, if your order and payment is received at 2:00 p.m. on Friday, delivery will be made no later than 6:00 p.m. the following Friday.</p><p>Free Mainland UK shipping is included on all orders. Deliveries to the Scottish Highlands, Northern Ireland and the Channel Islands may take a little longer.</p>"}');
INSERT INTO sections (page, type, name, position, enabled, data) VALUES
  ('page:returns', 'page', 'Returns', 1, 1, '{"title":"Returns","body":"<p>There are some circumstances where you may wish to return the products that you have ordered from us and this policy explains when and how you can do this.</p><p>If you change your mind about the products you have ordered, you may cancel your order at any time within 14 days of receiving the products. Please contact customerservice@chenfurniture.com with your order number and we will arrange collection or advise how to return the goods.</p>"}'),
  ('page:privacy', 'page', 'Privacy Policy', 1, 1, '{"title":"Privacy Policy","body":"<p>We only collect the information we need to process your order and to keep you up to date with news from Chen Furniture. We never sell your data.</p><p>If you join our newsletter you can unsubscribe at any time using the link at the bottom of every email, or by contacting customerservice@chenfurniture.com.</p>"}'),
  ('page:terms-and-conditions', 'page', 'Terms & Conditions', 1, 1, '{"title":"Terms & Conditions","body":"<p>By placing an order with Chen Furniture you agree to these terms. All prices are shown in GBP and include VAT where applicable.</p><p>Products remain the property of Chen Furniture until full payment has been received. Nothing in these terms affects your statutory rights.</p>"}'),
  ('page:contact-details', 'page', 'Contact Details', 1, 1, '{"title":"Contact Details","body":"<p>Customer Service: <a href=\"mailto:customerservice@chenfurniture.com\">customerservice@chenfurniture.com</a></p><p>We aim to reply within one working day, Monday to Friday.</p>"}');
INSERT INTO sections (page, type, name, position, enabled, data) VALUES
  ('page:store-locator', 'page', 'Store Locator', 1, 1, '{"title":"Store Locator","body":"<p>Prefer to try before you buy? Our bean bags are stocked by a growing list of independent retailers across the UK and Ireland.</p><p>Email customerservice@chenfurniture.com and we will point you to your nearest stockist.</p>"}'),
  ('page:about', 'page', 'About', 1, 1, '{"title":"About Chen Furniture","body":"<p>Chen Furniture makes bean bags, chairs and loungers for indoors and outdoors. The range is built around one idea: generous, sink-into-it comfort that suits the living room as well as the garden.</p><p>The fabrics are water resistant and UV resistant, so a shower of rain or a season in the sun is not a problem - every product page lists the features it was made with.</p><p>Questions about a product, an order or a return? Email <a href=\"mailto:customerservice@chenfurniture.com\">customerservice@chenfurniture.com</a> and we will reply within one working day, Monday to Friday.</p>"}'),
  ('page:faq', 'page', 'FAQ', 1, 1, '{"title":"FAQ","body":"<p><strong>How long does delivery take?</strong><br>Orders are delivered within 3-5 working days, and free Mainland UK shipping is included. See <a href=\"/pages/delivery\">Delivery Details</a>.</p><p><strong>Can I return an order?</strong><br>Yes - you can cancel within 14 days of receiving the products. See <a href=\"/pages/returns\">Returns</a>.</p><p><strong>Where can I see the products in person?</strong><br>Our bean bags are stocked by independent retailers across the UK and Ireland - see <a href=\"/pages/store-locator\">Store Locator</a>.</p><p><strong>How do I get in touch?</strong><br>Email <a href=\"mailto:customerservice@chenfurniture.com\">customerservice@chenfurniture.com</a> or see <a href=\"/pages/contact-details\">Contact Details</a>.</p>"}');
